#!/usr/bin/env python3
from pathlib import Path
import os,json,hashlib,html,sys
repo=Path(__file__).resolve().parents[1];sys.path.insert(0,str(repo/'backend/recal'))
from visual_review import digest_manifest,validate_draft
root=Path.home()/'Movies/Ambient-Field-Lens/2026-10-28/visual-grounding-review';manifest=json.loads((root/'manifest.json').read_text());validate_draft(manifest)
parts=[]
for p in manifest['pairs']:
 images=[]
 for m in p['members']:
  src=os.path.relpath(m['image_asset'],root);overlay=''
  if p.get('visual_target'):
   points=' '.join(f'{x},{y}' for x,y in p['visual_target']['points_xy'])
   overlay=f'<svg viewBox="0 0 {m["width"]} {m["height"]}" aria-label="Provided image-space footprint"><polygon points="{points}" fill="none" stroke="#00d9e8" stroke-width="2"/></svg>'
  raw=os.path.relpath(m['archived_source'],root)
  images.append(f'''<div><h3>Image {m['id'][-1]}</h3><div class="image"><img src="{src}" alt="Image {m['id'][-1]} for {html.escape(p['check'])}">{overlay}</div><p class="meta">Native crop {m['width']}×{m['height']} · <a href="{src}" target="_blank">open crop</a> · <a href="{raw}" target="_blank">archived source</a></p><label>Your image label <select id="label-{m['id']}"><option value="">Unreviewed</option><option value="pass">Pass — candidate supported</option><option value="fail">Fail — candidate contradicted</option><option value="unknown">Unknown — cannot see enough</option><option value="reject">Reject this member</option></select></label></div>''')
 proposal=', '.join(m['id'][-1]+': '+m['author_proposed_label'] for m in p['members'])
 parts.append(f'''<article><p class="meta">{p['id']} · {html.escape(p['check'])} · {p['fold']} · capture family {html.escape(p['capture_group'])}</p><h2>{html.escape(p['question'])}</h2><p><b>Same candidate for both images:</b> {html.escape(p['candidate'])}</p><p>{html.escape(p['scope'])}</p><div class="pair">{''.join(images)}</div><div class="assess"><label>Requires the image, rather than manual text alone? <select id="image-required-{p['id']}"><option value="">Unreviewed</option><option value="yes">Yes — image required</option><option value="no">No — discard the pair</option></select></label><label>Both states visually resolvable? <select id="sufficient-{p['id']}"><option value="">Unreviewed</option><option value="yes">Yes</option><option value="no">No — reject or replace</option></select></label><label>Correction / note <textarea id="note-{p['id']}" rows="2"></textarea></label></div><details><summary>Author proposal and limitations — proposed labels, not your sign-off</summary><p>{html.escape(proposal)}</p><p>{html.escape(p['author_note'])}</p></details></article>''')
head='''<!doctype html><meta charset="utf-8"><title>Archived visual grounding — Miguel review</title><style>body{font:17px system-ui;max-width:1280px;margin:35px auto;padding:0 25px;background:#f6f4ed;color:#172a35}h1{font-size:38px}h2{font-size:24px;line-height:1.45}p{line-height:1.6}.meta{font-size:14px;color:#5a6b74}article{border-top:1px solid #bac9c2;margin-top:35px;padding-top:25px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:25px}.image{position:relative;width:100%;background:white}.image img{display:block;width:100%;height:auto;image-rendering:pixelated}.image svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}select,input,textarea{font:inherit;padding:9px;border:1px solid #99aaa4;border-radius:5px;background:white;color:#172a35}label{display:block;margin:14px 0}textarea{display:block;width:95%}.assess{margin:20px 0;padding:12px 20px;background:#e5eee9}button{font:inherit;padding:12px 20px;background:#174e43;color:white;border:0;border-radius:6px;cursor:pointer}details{margin-top:15px}summary{cursor:pointer;color:#45645b}.banner{padding:20px;background:#e4eee8;border-radius:8px}.release{padding:25px;border:2px solid #708e81;margin:40px 0}a{color:#1c7764}@media(max-width:850px){.pair{grid-template-columns:1fr}}</style>'''
intro='''<h1>Archived visual-grounding pairs</h1><div class="banner"><b>Four pairs / eight image conditions — your review is required before any scoring.</b><p>Each pair has the same question and candidate. Only the image condition changes. No manual answer, controller flags, capture labels or source filenames will be given to a model. These are native-pixel crops from archived recordings; zooming does not create detail.</p><p>Label both images yourself. Unknown, insufficient visibility, a rejected pair, or manual-only answerability blocks the set. Author labels are hidden below each pair; they are proposals only.</p></div><p><b>Footprint scope:</b> the cyan polygon is an explicitly supplied image-space target, held fixed across the two archived scenes. It is a reference graphic over the unchanged crop, not a recovered robot toolpath or accepted calibration. Reject the pair if that is not the check you intend.</p><p><b>Drawing completeness:</b> the question concerns missing edge strokes of an outline. Its unfilled interior is intentional. This is a four-pair seed, with only one test pair, not an accuracy benchmark.</p>'''
release='''<section class="release"><h2>Your independent review</h2><label>Your name <input id="reviewer" autocomplete="off" placeholder="Enter your own name"></label><label><input type="checkbox" id="scope"> I accept the footprint pair as an image-space containment task, not registered robot geometry.</label><label><input type="checkbox" id="independent"> I independently reviewed every image and the question scope. These labels and corrections are my own.</label><p><button onclick="downloadReview()">Download my review JSON</button></p><p id="status" class="meta">No labels have been submitted or frozen. This page makes no model calls and launches nothing.</p><p>A completed review can be handed to Codi/Muse for a separate freeze and offline-scoring plan. Downloading a partial review does not authorize scoring. /assist remains default-deny.</p></section>'''
data={'digest':digest_manifest(manifest),'pairs':[{'id':p['id'],'member_ids':[m['id'] for m in p['members']]} for p in manifest['pairs']]}
script='''<script>const packet=DATA;function val(id){return document.getElementById(id).value}function downloadReview(){const pairs=packet.pairs.map(p=>({id:p.id,manual_only_answerable:val('image-required-'+p.id)==='yes'?false:val('image-required-'+p.id)==='no'?true:null,image_evidence_sufficient:val('sufficient-'+p.id)==='yes'?true:val('sufficient-'+p.id)==='no'?false:null,member_labels:Object.fromEntries(p.member_ids.map(id=>[id,val('label-'+id)||null])),note:val('note-'+p.id)}));const r={schema:'visual-grounding-human-review-v1',manifest_digest:packet.digest,reviewer_name:val('reviewer').trim(),independently_reviewed:document.getElementById('independent').checked,footprint_scope_approved:document.getElementById('scope').checked,reviewed_at:new Date().toISOString(),pairs};const complete=r.reviewer_name.toLowerCase().includes('miguel')&&r.independently_reviewed&&r.footprint_scope_approved&&pairs.every(p=>p.manual_only_answerable===false&&p.image_evidence_sufficient===true&&JSON.stringify(Object.values(p.member_labels).sort())===JSON.stringify(['fail','pass']));r.status=complete?'human_review_complete_pending_freeze':'draft_incomplete';r.gpu_launched=false;r.live_green_enabled=false;const blob=new Blob([JSON.stringify(r,null,2)+'\\n'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='visual-grounding-human-review-2026-10-28.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);document.getElementById('status').textContent=complete?'Review downloaded. No scoring has run; hand the JSON to Codi/Muse for verification and freeze.':'Partial review downloaded. Missing, unknown, rejected or text-answerable items still block scoring.'}</script>'''.replace('DATA',json.dumps(data))
(root/'review.html').write_text(head+intro+''.join(parts)+release+script)
print('Review ready:',root/'review.html')
